/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - Vpotula
/// This class is derived from <c>CustSumForPaym</c> for cater for AMEX generate payments.
/// </summary>
using Microsoft.Dynamics365.LocalizationFramework;
class METAMEXCustSumForPaym extends CustSumForPaym
{
}

Method.Source:
    /// <summary>
    /// Create new instance of <c>METAMEXCustSumForPaym</c> class.
    /// </summary>
    /// <param name = "_ledgerJournalId">Journal number to generate payments.</param>
    /// <returns><c>METAMEXCustSumForPaym</c>class instance</returns>
    static METAMEXCustSumForPaym construct(LedgerJournalId  _ledgerJournalId)
    {
        LedgerJournalTable          ledgerJournalTable = LedgerJournalTable::find(_ledgerJournalId);
        METAMEXCustSumForPaym       custVendSumForPaym = new METAMEXCustSumForPaym();

        if (!ledgerJournalTable)
        {
            throw error("@SYS19282");
        }
        custVendSumForPaym.parmLedgerJournalId(_ledgerJournalId);
        custVendSumForPaym.initParmDefault();

        custVendSumForPaym.updateQuery();

        return custVendSumForPaym;
    }

    /// <summary>
    /// Construct the class instance and triggers the generate payments operation.
    /// </summary>
    /// <param name = "_args">A set of arguments for generating payments.</param>
    public static void main(Args _args)
    {
        METAMEXCustSumForPaym  custSumForPaym;

        switch (_args.dataset())
        {
            case tableNum(LedgerJournalTable) :
                custSumForPaym = METAMEXCustSumForPaym::newLedgerJournalTable(_args.record());
                break;

            default :
                throw error(Error::wrongUseOfFunction("@SYS24287"));
        }

        custSumForPaym.parmArgs(_args);

        custSumForPaym.runOperation();
    }

    /// <summary>
    /// Create new instance of <c>METAMEXCustSumForPaym</c> class.
    /// </summary>
    /// <param name = "_ledgerJournalTable">LedgerJournalTable buffer.</param>
    /// <returns><c>METAMEXCustSumForPaym</c> instance</returns>
    static METAMEXCustSumForPaym newLedgerJournalTable(LedgerJournalTable  _ledgerJournalTable)
    {
        METAMEXCustSumForPaym  custSumForPaym;

        custSumForPaym = METAMEXCustSumForPaym::construct(_ledgerJournalTable.JournalNum);

        return custSumForPaym;
    }

    /// <summary>
    /// Initialising default parameters such as payment mode and bank acocunt id.
    /// </summary>
    public void initParmDeFault()
    {
        LedgerJournalTrans  ledgerJournalTrans;
        super();

        if (ledgerJournalId)
        {
            select  firstonly ledgerJournalTrans 
                where ledgerJournalTrans.JournalNum == ledgerJournalId
                && ledgerJournalTrans.PaymMode;
            this.parmPaymMode(ledgerJournalTrans.PaymMode);
            this.parmBankAccountID(ledgerJournalTrans.parmOffsetAccount());
        }

    }

    /// <summary>
    /// Runs the generate payment operation.
    /// </summary>
    public void run()
    {
        CustVendPaymModeTable custVendPaymModeTable;

        if (!selectOnPaymFormat && paymMode)
        {
            custVendPaymModeTable = this.paymModeTable();

            if (this.useGERConfiguration())
            {
                this.exportERPayment(custVendPaymModeTable.ERFormatMappingID);
            }
        }
    }

    /// <summary>
    /// Run electronic report to generate payment file. 
    /// </summary>
    /// <param name = "_eRFormatMappingID">ER format</param>
    void exportERPayment(ERFormatMappingID _eRFormatMappingID)
    {
        ERIFileDestination erFileDestination   = ERObjectsFactory::createFileDestinationBrowser();
        Date sysDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        #Define.UserIdentification('parameter.userIdentification')

        //erFileDestination.newFileStream()
        var custVendPaymERExport = new CustVendPaymERExport();
        custVendPaymERExport.parmERBinding(_eRFormatMappingID);
        custVendPaymERExport.parmLedgerJournalId(ledgerJournalId);
        custVendPaymERExport.parmBankAccountID(bankAccountID);
        custVendPaymERExport.parmERFileName(ledgerJournalId);
        custVendPaymERExport.parmQuery(this.queryRun().query());
        custVendPaymERExport.parmShowParamsDialog(false);
        custVendPaymERExport.parmCustVendPaymModeTable(this.paymModeTable());
        custVendPaymERExport.parmShowDialog(false);
        custVendPaymERExport.parmShowParamsDialog(false);

        //str userId =  subStr(ledgerJournalId, 2,10);
        //custVendPaymERExport.addInputParameter(#UserIdentification, userId);
        custVendPaymERExport.run();
    }
